void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
int main(){try{tracking=true;Config c;for(unsigned age=0;age<65536;++age){c=Config{};c.age=age;c.start=age&255;run(c);}for(unsigned part=0;part<256;++part)for(unsigned base=0;base<256;++base){c=Config{};c.kind=K::Signal;c.part=part;c.base=base;run(c);}for(unsigned count:{0u,1u,2u,127u,128u,255u})for(unsigned part:{0u,3u,127u,255u})for(unsigned pattern=0;pattern<4;++pattern){c=Config{};c.count=count;c.part=part;c.pattern=pattern;run(c);}for(unsigned fault:{1u,2u})for(auto kind:{K::Voices,K::Signal}){c=Config{};c.kind=kind;c.fault=fault;run(c);}for(unsigned busy:{1u,2u,255u}){c=Config{};c.busy=busy;run(c);}c=Config{};c.live=true;run(c);tracking=false;check(!allocations&&kinds==3&&components==0x3ff&&faultCases==4,"Reload voice graph coverage/allocation differs");std::printf("PASS: %llu pure reload voice/signal graphs; %llu phases; %llu rejected budgets; components=%x; %llu complete65536retry faults; all ages/slots/parts/count0 wrap, live resources, exact DSP bytes and Down map, zero allocations\n",(unsigned long long)cases,(unsigned long long)phases,(unsigned long long)rejected,components,(unsigned long long)faultCases);return 0;}catch(const std::exception&e){tracking=false;std::fprintf(stderr,"%s\n",e.what());return 1;}}
